SELECT 'gongkao', '兄弟姐妹关系', 'kp-age-mp-siblings', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "兄弟姐妹关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "暗含了等差数列的逻辑。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“家有四个兄妹，依次相差两岁。四人总和 40 岁”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[看出是等差数列] --> B[总年龄 ÷ 人数 = 平均年龄(中位数)]\nB --> C{人数是奇数还是偶数?}\nC -- 奇数(3个/5个) --> D[平均年龄就是正中间那个人的年龄]\nC -- 偶数(4个/6个) --> E[平均年龄卡在中间两个人中间]\nE --> F[根据年龄差 d, 两人分别是 平均+d/2 和 平均-d/2]"}}]}$$ AS jsonb), NULL, '兄弟姐妹关系的核心考点与实战推导。', category_node.id, CAST('["数量关系", "年龄问题", "兄弟姐妹关系"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_age_mp_siblings", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
